SELECT 


    AND m.account_id = #{accountId}
    AND s.warehouse_id = #{warehouseId}

        AND (s.sku LIKE CONCAT('%', #{keyword}, '%') OR mt.name LIKE CONCAT('%', #{keyword}, '%'))

    AND (s.material_id IS NULL OR s.available_qty + s.locked_qty <> COALESCE(e.qty, 0))

ORDER BY ABS(s.available_qty + s.locked_qty - COALESCE(e.qty, 0)) DESC, s.sku

SELECT COUNT(*) AS "skuCount",
       SUM(CASE WHEN s.material_id IS NULL OR s.available_qty + s.locked_qty <> COALESCE(e.qty, 0) THEN 1 ELSE 0 END) AS "diffCount",
       SUM(s.available_qty) AS "available", SUM(s.transit_qty) AS "transit", SUM(s.locked_qty) AS "locked",
       SUM(COALESCE(e.qty, 0)) AS "erpQty", MAX(s.sync_time) AS "syncTime"


    AND m.account_id = #{accountId}
    AND s.warehouse_id = #{warehouseId}

SELECT 

WHERE s.id IN #{id}
ORDER BY s.warehouse_id, s.id
